// Lightweight bilingual helpers. Pure (no React) so both server and client
// modules can import the types and resolvers.

export type Lang = "ru" | "en";

export const LANGS: Lang[] = ["ru", "en"];
export const DEFAULT_LANG: Lang = "ru";

/** A localized string. */
export type L = { ru: string; en: string };
/** A localized list of strings. */
export type LList = { ru: string[]; en: string[] };

/** Resolve a localized string (or a plain string) for the active language. */
export function tr(value: L | string, lang: Lang): string {
  return typeof value === "string" ? value : value[lang];
}

/** Resolve a localized list (or a plain array) for the active language. */
export function trList(value: LList | string[], lang: Lang): string[] {
  return Array.isArray(value) ? value : value[lang];
}
